package ui.icons

import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * The Tabler set is generated by tools/tabler-codegen, which embeds upstream SVG path data
 * verbatim and hands it to Compose's PathParser on first access. A path string that fails to
 * parse, or that parses into a shape outside Tabler's 24x24 grid, is invisible in a diff and
 * only shows up as an icon that silently renders wrong -- so parse every glyph and look at
 * the geometry that comes out.
 */
class TablerIconsTest {

    private val glyphs: Map<String, ImageVector> = with(TablerIcons) {
        mapOf(
            "Accessible" to Accessible,
            "AlertTriangle" to AlertTriangle,
            "ArrowLeft" to ArrowLeft,
            "ArrowsMaximize" to ArrowsMaximize,
            "Ban" to Ban,
            "Bell" to Bell,
            "BellOff" to BellOff,
            "CameraPlus" to CameraPlus,
            "CameraRotate" to CameraRotate,
            "ChartBar" to ChartBar,
            "Check" to Check,
            "Checks" to Checks,
            "ChevronDown" to ChevronDown,
            "ChevronLeft" to ChevronLeft,
            "ChevronRight" to ChevronRight,
            "CircleCheck" to CircleCheck,
            "CirclePlus" to CirclePlus,
            "Code" to Code,
            "Compass" to Compass,
            "Copy" to Copy,
            "Crop" to Crop,
            "DeviceDesktop" to DeviceDesktop,
            "DeviceGamepad" to DeviceGamepad,
            "Dots" to Dots,
            "DotsVertical" to DotsVertical,
            "Download" to Download,
            "ExternalLink" to ExternalLink,
            "FileMusic" to FileMusic,
            "FileText" to FileText,
            "FileZip" to FileZip,
            "Fingerprint" to Fingerprint,
            "HandStop" to HandStop,
            "Headphones" to Headphones,
            "HeadphonesOff" to HeadphonesOff,
            "Headset" to Headset,
            "Heart" to Heart,
            "Home" to Home,
            "InfoCircle" to InfoCircle,
            "Language" to Language,
            "LayoutGrid" to LayoutGrid,
            "Lock" to Lock,
            "Logout" to Logout,
            "Mail" to Mail,
            "Maximize" to Maximize,
            "Message" to Message,
            "Microphone" to Microphone,
            "MicrophoneOff" to MicrophoneOff,
            "Minimize" to Minimize,
            "MoodSmile" to MoodSmile,
            "Music" to Music,
            "Palette" to Palette,
            "Paperclip" to Paperclip,
            "Pencil" to Pencil,
            "Phone" to Phone,
            "PhoneOff" to PhoneOff,
            "Photo" to Photo,
            "Pin" to Pin,
            "PlayerPause" to PlayerPause,
            "PlayerPlay" to PlayerPlay,
            "Plus" to Plus,
            "School" to School,
            "Search" to Search,
            "Server" to Server,
            "Settings" to Settings,
            "SettingsAutomation" to SettingsAutomation,
            "Shield" to Shield,
            "Speakerphone" to Speakerphone,
            "Stars" to Stars,
            "Trash" to Trash,
            "User" to User,
            "UserOff" to UserOff,
            "Users" to Users,
            "Video" to Video,
            "VideoOff" to VideoOff,
            "Volume" to Volume,
            "Volume2" to Volume2,
            "WaveSine" to WaveSine,
            "Window" to Window,
            "World" to World,
            "X" to X
        )
    }

    @Test
    fun everyGlyphBuildsOnTheTablerGrid() {
        assertEquals(80, glyphs.size)

        glyphs.forEach { (name, vector) ->
            assertEquals(24f, vector.viewportWidth, "$name viewportWidth")
            assertEquals(24f, vector.viewportHeight, "$name viewportHeight")
            assertEquals(
                name,
                vector.name,
                "the primary symbol must carry its own name, not the Outline twin's"
            )
        }
    }

    @Test
    fun everyGeneratedPathParsesIntoGeometryInsideTheGrid() {
        assertEquals(127, TablerGlyphs.size)

        TablerGlyphs.forEach { (name, glyph) ->
            assertTrue(glyph.paths.isNotEmpty(), "$name has no paths")

            var left = Float.MAX_VALUE
            var top = Float.MAX_VALUE
            var right = -Float.MAX_VALUE
            var bottom = -Float.MAX_VALUE

            glyph.paths.forEachIndexed { i, data ->
                val path = PathParser().parsePathString(data).toPath()
                assertTrue(!path.isEmpty, "$name path $i parsed to nothing")
                val b = path.getBounds()
                left = minOf(left, b.left)
                top = minOf(top, b.top)
                right = maxOf(right, b.right)
                bottom = maxOf(bottom, b.bottom)
            }

            assertTrue(right > left, "$name has zero width: [$left, $right]")
            assertTrue(bottom > top, "$name has zero height: [$top, $bottom]")
            // A 2px stroke on a 24px grid may bleed half a unit past the viewBox.
            assertTrue(left >= -1f && top >= -1f, "$name escapes the grid at ($left, $top)")
            assertTrue(right <= 25f && bottom <= 25f, "$name escapes the grid at ($right, $bottom)")
        }
    }

    /**
     * Orbit asks for the filled style, so the question is never "does TablerIcons.Heart
     * compile" but "is it actually solid". These are the 47 of 80 symbols with an upstream
     * filled variant; each also emits an Outline twin. Regenerating against a Tabler release
     * that drops a filled variant deletes that twin and fails here -- which is the moment
     * worth knowing about, because it means a screen silently fell back to line art.
     */
    @Test
    fun symbolsWithAFilledVariantAlsoShipTheirOutlineTwin() {
        val expectedFilled = setOf(
            "Accessible", "AlertTriangle", "Bell", "Check", "ChevronDown", "ChevronRight",
            "CircleCheck", "CirclePlus", "Compass", "Copy", "DeviceDesktop", "DeviceGamepad",
            "Dots", "DotsVertical", "Download", "ExternalLink", "FileMusic", "FileText",
            "Headphones", "Headset", "Heart", "Home", "InfoCircle", "LayoutGrid", "Lock",
            "Mail", "Message", "Microphone", "MoodSmile", "Palette", "Pencil", "Phone",
            "Photo", "Pin", "PlayerPause", "PlayerPlay", "Plus", "School", "Search",
            "Settings", "Shield", "Stars", "Trash", "User", "Video", "World", "X"
        )

        val actualFilled = TablerGlyphs.keys
            .filter { it.endsWith("Outline") }
            .map { it.removeSuffix("Outline") }
            .toSet()

        assertEquals(expectedFilled, actualFilled)

        expectedFilled.forEach { symbol ->
            val filled = TablerGlyphs.getValue(symbol)
            val outline = TablerGlyphs.getValue("${symbol}Outline")
            assertTrue(!filled.stroke, "$symbol primary should be filled")
            assertTrue(outline.stroke, "$symbol Outline twin should be stroked")
            assertTrue(
                filled.paths.sumOf { it.length } > outline.paths.sumOf { it.length } ||
                    // A few upstream "filled" glyphs (X, Check, the chevrons) are strokes
                    // with no interior to fill, so only require they differ at all.
                    filled.paths != outline.paths,
                "$symbol filled variant is identical to its outline twin"
            )
        }
    }
}
